import * as ImageManipulator from 'expo-image-manipulator';

import fixtureJson from '../fixtures/exif_orientation_fixture.json';
import { base64ToUint8Array, decodeJpegToRgb, preprocessImageUri } from '../preprocess';

/**
 * Portrait photos arrive stored landscape with EXIF orientation 6. `jpeg-js` ignores
 * EXIF, so the app relies on the native resize step (`expo-image-manipulator`, which
 * decodes through Glide and applies the orientation) to hand it upright pixels.
 * The fixture is generated by `ml/scripts/build_exif_fixture.py`.
 */

interface ExifFixture {
  orientation: number;
  stored_width: number;
  stored_height: number;
  size: number;
  quadrant_colors: Record<string, [number, number, number]>;
  exif_jpeg_base64: string;
  upright_jpeg_base64: string;
  upright_probes: { row: number; col: number; rgb: [number, number, number] }[];
}

const fixture = fixtureJson as unknown as ExifFixture;

// jpeg-js and Pillow's libjpeg-turbo use different IDCTs; a few levels is expected.
const PIXEL_TOLERANCE = 3;
const COLOR_TOLERANCE = 6;

function pixelAt(rgb: Uint8Array, width: number, row: number, col: number): number[] {
  const i = (row * width + col) * 3;
  return [rgb[i] ?? 0, rgb[i + 1] ?? 0, rgb[i + 2] ?? 0];
}

function readExifOrientation(jpeg: Uint8Array): number | null {
  // APP1 "Exif\0\0" segment, then a TIFF header; find tag 0x0112 in IFD0.
  for (let i = 2; i + 4 < jpeg.length;) {
    if (jpeg[i] !== 0xff) return null;
    const marker = jpeg[i + 1] ?? 0;
    const length = ((jpeg[i + 2] ?? 0) << 8) | (jpeg[i + 3] ?? 0);
    if (marker === 0xe1 && String.fromCharCode(...jpeg.slice(i + 4, i + 8)) === 'Exif') {
      const tiff = i + 10;
      const little = jpeg[tiff] === 0x49;
      const read16 = (o: number) =>
        little
          ? (jpeg[o] ?? 0) | ((jpeg[o + 1] ?? 0) << 8)
          : ((jpeg[o] ?? 0) << 8) | (jpeg[o + 1] ?? 0);
      const read32 = (o: number) =>
        little ? read16(o) + read16(o + 2) * 0x10000 : read16(o) * 0x10000 + read16(o + 2);
      const ifd = tiff + read32(tiff + 4);
      const entries = read16(ifd);
      for (let e = 0; e < entries; e++) {
        const entry = ifd + 2 + e * 12;
        if (read16(entry) === 0x0112) return read16(entry + 8);
      }
      return null;
    }
    i += 2 + length;
  }
  return null;
}

function quadrantMean(
  rgb: Uint8Array,
  width: number,
  height: number,
  quadrant: string,
  margin = 16,
): number[] {
  const halfW = Math.floor(width / 2);
  const halfH = Math.floor(height / 2);
  const top = quadrant.startsWith('top');
  const left = quadrant.endsWith('left');
  const rows = top ? [margin, halfH - margin] : [halfH + margin, height - margin];
  const cols = left ? [margin, halfW - margin] : [halfW + margin, width - margin];
  const sum = [0, 0, 0];
  let count = 0;
  for (let r = rows[0] ?? 0; r < (rows[1] ?? 0); r++) {
    for (let c = cols[0] ?? 0; c < (cols[1] ?? 0); c++) {
      const [red = 0, green = 0, blue = 0] = pixelAt(rgb, width, r, c);
      sum[0] = (sum[0] ?? 0) + red;
      sum[1] = (sum[1] ?? 0) + green;
      sum[2] = (sum[2] ?? 0) + blue;
      count++;
    }
  }
  return sum.map((value) => value / count);
}

function expectClose(actual: number[], expected: number[], tolerance: number): void {
  actual.forEach((value, index) => {
    expect(Math.abs(value - (expected[index] ?? 0))).toBeLessThanOrEqual(tolerance);
  });
}

describe('EXIF orientation fixture', () => {
  it('is a landscape-stored JPEG tagged with orientation 6', () => {
    const jpeg = base64ToUint8Array(fixture.exif_jpeg_base64);
    expect(readExifOrientation(jpeg)).toBe(6);
    expect(fixture.orientation).toBe(6);
  });

  it('shows that jpeg-js ignores EXIF, so the native step must rotate', () => {
    const { width, height, rgb } = decodeJpegToRgb(base64ToUint8Array(fixture.exif_jpeg_base64));
    expect([width, height]).toEqual([fixture.stored_width, fixture.stored_height]);
    // Stored pixels are the upright view turned 90 degrees counter-clockwise.
    expectClose(
      quadrantMean(rgb, width, height, 'top_left'),
      fixture.quadrant_colors.top_right ?? [],
      COLOR_TOLERANCE,
    );
  });

  it('turns the native upright output into the tensor Python expects', async () => {
    const manipulate = jest.spyOn(ImageManipulator, 'manipulateAsync').mockResolvedValue({
      uri: 'file:///cache/resized.jpg',
      width: fixture.size,
      height: fixture.size,
      base64: fixture.upright_jpeg_base64,
    });

    const tensor = await preprocessImageUri('file:///photos/portrait.jpg');

    // Only a resize is requested: orientation is left to the native decoder.
    expect(manipulate).toHaveBeenCalledWith(
      'file:///photos/portrait.jpg',
      [{ resize: { width: 224, height: 224 } }],
      expect.objectContaining({ base64: true }),
    );
    expect(tensor.length).toBe(fixture.size * fixture.size * 3);

    for (const probe of fixture.upright_probes) {
      const i = (probe.row * fixture.size + probe.col) * 3;
      const expected = probe.rgb.map((value) => (value - 127.5) / 127.5);
      expectClose(
        [tensor[i] ?? 0, tensor[i + 1] ?? 0, tensor[i + 2] ?? 0],
        expected,
        PIXEL_TOLERANCE / 127.5,
      );
    }
    manipulate.mockRestore();
  });

  it('decodes the upright reference with quadrants in their upright places', () => {
    const { width, height, rgb } = decodeJpegToRgb(base64ToUint8Array(fixture.upright_jpeg_base64));
    expect([width, height]).toEqual([fixture.size, fixture.size]);
    for (const [quadrant, color] of Object.entries(fixture.quadrant_colors)) {
      expectClose(quadrantMean(rgb, width, height, quadrant), color, COLOR_TOLERANCE);
    }
  });
});
